-- MapRiders road-following route POIs for vip-bike:
-- Generated via OSRM (router.project-osrm.org) — each route has a geojson LineString
-- with hundreds of intermediate points that follow actual roads.
-- RacingMap.tsx renders poi.geojson via <GeoJSON> component (not <Polyline>).
--
-- Routes:
-- 1) Городской круиз (green, loop) — downtown center, ~25km
-- 2) Набережный спринт (blue, path) — Oka embankment, ~4km
-- 3) Мостовой кольцевой (amber, loop) — Metro + Molitovsky bridges, ~14km
-- 4) Оффроуд между мостами (red, dashed loop) — Meshchersky Park perimeter, ~6km

with target_map as (
  select id
  from public.maps
  order by
    case
      when lower(coalesce(metadata->>'crew_slug', metadata->>'crewSlug', metadata->>'slug', '')) = 'vip-bike' then 0
      when is_default then 1
      else 2
    end,
    created_at desc
  limit 1
),
existing_non_routes as (
  select m.id,
         coalesce(
           jsonb_agg(poi) filter (where coalesce(poi->>'id', '') !~ '^vip-route-'),
           '[]'::jsonb
         ) as keep_pois
  from public.maps m
  join target_map t on t.id = m.id
  left join lateral jsonb_array_elements(coalesce(m.points_of_interest, '[]'::jsonb)) poi on true
  group by m.id
),
default_routes as (
  select jsonb_build_array(
    jsonb_build_object(
